NULL, '2026-09-13 09:12:46', '2026-09-13 17:44:51');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('f2312eef-128a-4a67-8c87-e714c8cb8e9d', '7613eab2-a0b1-4c33-9d7c-096691758931', 'AK Roofing & Waterproofing', 'ak-roofing-waterproofing', NULL, 'AK Roofing & Waterproofing provides residential and commercial constructional improvement services to clients in New York City. It installs and repairs roofing systems using shingle and flat materials. Its crew conducts skylight installation to bring natural air and lighting to the property. Additionally, the company offers various general contracting services, including masonry works, brick pointing, foundation wall maintenance, and structure waterproofing. AK Roofing & Waterproofing has been in the industry for more than nine years.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/ak-roofing-waterproofing.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174454Z&X-Amz-Expires=43200&X-Amz-Signature=fff862003a9031d9c414a9e67b8b301d620992576f32c932c6c7c8317c069a9d&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '6464920756', 'akroofing3d@gmail.com', 'https://akroofing3d.com/', '666 Hemlock St', 'Brooklyn', 'NY', '11208', 'Brooklyn', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 23, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:48', '2026-09-13 17:44:54');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('25a0fd8f-b31b-4328-a293-4220b6f8f2b0', 'dcbb2d74-5025-4627-b61c-ac4cfcdc6832', 'Padovani Roofing & Construction', 'padovani-roofing-construction', NULL, 'Padovani Roofing & Construction serves New York City and the surrounding boroughs, offering comprehensive roofing services for both residential and commercial clients. It takes on projects involving roof installations and repairs using materials from various manufacturers. Its team also handles home improvement projects, including skylight installations, siding, chimney work, and louver installations. The company is a GAF Master Elite Contractor, IKO Certified, and Firestone Certified for EPDM and TPO flat roofing systems. It also provides special accommodations for veterans.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/padovani-roofing-construction.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174500Z&X-Amz-Expires=43200&X-Amz-Signature=4118ab38022a88fad64685ef896cccf6d576f81daacf235614e1be58c2119ad7&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '9088062276', 'padovaniconstruction@gmail.com', 'https://www.roofingnewjersey.com/', 'Neshanic Station, NJ 08853', 'Neshanic Station', 'NJ', '08853', 'New York City', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:52', '2026-09-13 17:45:01');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('91af576b-dbec-46d7-ad2f-6b056a84c114', '6970c440-af5a-4cf9-b96d-f9144593d825', 'Ramapo Valley Contracting', 'ramapo-valley-contracting', NULL, 'Ramapo Valley Contracting serves homes and businesses in New York City and the surrounding areas.  It installs and repairs shingle and standing seam roofs, providing curb appeal and protection from the elements. The company also works with owners and tenants to revitalize outdated office spaces, transforming them into modern, functional, and aesthetically appealing work environments. The team handles new construction, custom carpentry, and interior finish work, striving to achieve exceptional results that enhance a property\'s value and durability.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/ramapo-valley-contracting.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174504Z&X-Amz-Expires=43200&X-Amz-Signature=7f92c094e775446464d87dd3312fc2aa35d8316ca8d5c1493641342faf4b40f9&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '9737673162', 'nhall@rvcontracting.com', 'https://www.rvcontracting.com/', '852 Franklin Avenue STE 121', 'Franklin Lakes', 'NJ', '07417', 'New York City', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:54', '2026-09-13 17:45:04');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('58be07a1-5640-44b3-9915-682f0692593f', '3a226554-986b-4846-96c1-3c42a602329b', 'Gibraltar Home Improvements Inc', 'gibraltar-home-improvements-inc', NULL, 'Gibraltar Home Improvements Inc. is a family-owned and family-operated business that has been catering to clients in New York City since 1979. It offers roofing installation and remodeling services. It also handles every step of home remodeling projects, from initial consultation and design to completion. The company has received a 4.8-star Google rating based on more than 200 reviews. It was selected as the Best Roofing Company by Bethpage Federal Credit Union from 2023 to 2024.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/gibraltar-home-improvements-inc.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174507Z&X-Amz-Expires=43200&X-Amz-Signature=9693dc1190d7b36b907b047b652dd351df0713dddbf5ca68309710a6ca64f393&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '5164082500', 'info@gibraltarhi.com', 'https://www.gibraltarhi.com/', '483 Franklin Ave', 'Franklin Square', 'NY', '11010', 'Queens', NULL, NULL, 25, NULL, 1979, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:56', '2026-09-13 17:45:07');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('cb76490a-4f83-484a-a42d-b4adf1f8a95b', '25d07359-9bac-431d-8f71-b5b06e2f97b8', 'Al\'s Contracting', 'als-contracting', NULL, 'Al\'s Contracting has been providing roofing solutions to residential clients in New York City and the surrounding metros for more than 30 years. It preserves clients\' property investments by taking care of their need for regular roof installations, new construction, and re-roofing. Its team of roofers handles various types and materials to complete projects, such as lifetime asphalt shingles, roll roofing, rubber roofs, metal roofs, and Mediterranean tile, according to clients\' specifications and requirements. Al\'s Contracting utilizes major brands, including GAF, Atlas, Tamko, and Owens Corning.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/als-contracting.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174513Z&X-Amz-Expires=43200&X-Amz-Signature=6b2c33731bb169b54fdb3b1e237011ba14e70e7f469ea1f6093be8afe0319c59&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '9086840186', 'alsroofing@yahoo.com', 'https://www.alsroofingsiding.com/', '2 James Ct', 'Hackettstown', 'NJ', '07840', 'New York City', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:13:00', '2026-09-13 17:45:13');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('fcb5bcb4-2cd1-4693-9a1b-78fbef952eb1', 'b1cb1653-70c5-4e26-bfab-7ff18d8a67d1', 'A & B Roofing Corp.', 'a-b-roofing-corp', NULL, 'A & B Roofing Corp. works on the roofing projects of clients in New York City. The locally owned, family-run business offers a complete suite of services for all roofing needs, from repairs and replacements to new construction and preventative maintenance. It tailors services following a consultative process, taking the time to learn about each client\'s needs, wants, and precise roofing specifications. In addition, the company is able to help with gutter installation and cleaning, as well as siding installation.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/a-b-roofing-corp.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174516Z&X-Amz-Expires=43200&X-Amz-Signature=0ecad84e169a33091e7bbe838f0b0f41e073aae6aa3446e3c0ff8f44c6a710fa&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '7189815226', 'info@abroofingcorp.com', 'https://abroofingcorp.com/', 'Staten Island, NY 10302', 'Staten Island', 'NY', '10302', 'Staten Island', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:13:02', '2026-09-13 17:45:16');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('7afb3643-51a8-4298-9dd2-9b21fc41975b', 'e1e9b8ce-df0f-48d3-ab52-3758bde0a1a6', 'Jewel Construction Co', 'jewel-construction-co', NULL, 'Jewel Construction Co. Inc. serves property owners seeking renovation or remodeling solutions in and around New York City. For over 30 years, its team has been providing roofing services to help families and individuals improve the appeal of their properties. It works closely with customers to determine their project timeline and budget. It also performs deck installation and facade restoration. Jewel Construction Co. maintains affiliations with the NYC Landmarks Preservation Commission, the Department of Consumer Affairs NYC, and Brownstoner.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/jewel-construction-co.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174522Z&X-Amz-Expires=43200&X-Amz-Signature=43fba7e3d9ec97325c2c22e02cfdf16a67473362a2ed4145fa6c4400126ae935&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '473287203', 'jewelconstructionny@gmail.com', 'https://jewelconstructionny.com/', '3623 15th Ave', 'Brooklyn', 'NY', '11218', 'Brooklyn', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:13:05', '2026-09-13 17:45:23');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('65a83eac-f705-47b4-bc28-ef98a260c4c0', '66bc7b29-4a24-44de-8ef5-6024ad4f2051', 'SAS Roofing & Waterproofing', 'sas-roofing-waterproofing', NULL, 'SAS Roofing & Waterproofing is a family-owned and family-operated business serving clients in New York City and the surrounding areas. It caters to residential and commercial property owners in the market for roofing services. Its technicians carry out roof inspections, minor repairs, and new roof installations. They also apply waterproofing treatments on single-ply membrane roofs. In addition, the company takes on interior and exterior remodeling tasks, such as painting, plastering, stucco repair, flooring installation, and masonry.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/sas-roofing-waterproofing.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174529Z&X-Amz-Expires=43200&X-Amz-Signature=2012683d5fcd5d8ef68e3b537368656b06177fb9deb6367a073765e64235bbe6&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '3473949384', 'sascon09@yahoo.com', 'https://sasroofingwaterproofing.com/', '377 Ocean Pkwy #7B', 'Brooklyn', 'NY', '11218', 'Brooklyn', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 235, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:13:09', '2026-09-13 17:45:29');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('551a8a83-caa6-4769-bcb3-0745034de956', 'f08caa2f-c240-49d1-ab30-5b742051ca25', 'B&P Consulting Corp.', 'bp-consulting-corp', NULL, 'B&P Consulting Corp. is a family-owned and family-operated business that serves various customers throughout New York City, including residential property owners, engineers, business owners, and architects. For more than 15 years, the company has been installing flat roof systems, such as APP-modified bitumen,  extremely durable synthetic rubber roofing membrane (EPDM), asphalt and synthetic rubber, and thermoplastic polyolefin (TPO). It also handles foundation waterproofing and paver system installation. B&P Consulting collaborates with Westile Company and Hanover Architectural Products.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/bp-consulting-corp.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174458Z&X-Amz-Expires=43200&X-Amz-Signature=2f855147c6df4f2b74532a478542537ff662ef9ab58069400bda883fa412b605&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '6467153223', 'info@bnpconsulting.nyc', 'https://bnpconsulting.nyc/', '149 Norman Ave', 'Brooklyn', 'NY', '11222', 'Brooklyn', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 35, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:50', '2026-09-13 17:44:58');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('593fbb14-4aed-4eac-9e3b-54256b820949', '15356866-0c01-4dc2-85d4-14b1fbae1b8e', 'Chief Cornerstone Roofing', 'chief-cornerstone-roofing', NULL, 'Chief Cornerstone Roofing addresses the construction needs of customers throughout New York City. It provides residences and commercial establishments with a wide range of roofing solutions, including inspection, installation, repair and maintenance. Its technicians, who have years of industry experience, work with different types of roofing materials, such as metal, tile, and EPDM rubber roofing, as well as asphalt shingles. They prioritize longevity and reliability by using top-quality products, adhering to industry-standard processes, and paying close attention to detail, particularly when dealing with flat roofs.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/chief-cornerstone-roofing.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174509Z&X-Amz-Expires=43200&X-Amz-Signature=c7c1af5d1ff6cae32f63b02b6ae68f04537753a9a9f91c83d4ca6b795af3e6ee&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '5162736428', 'chiefcornerstoneinc@gmail.com', 'https://chiefcornerstonecontractorsinc.com/', '11 Katie Ct', 'Lake Grove', 'NY', '11755', 'New York City', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:58', '2026-09-13 17:45:10');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('00604942-583c-4c59-91d4-5d8a019aead3', '7978903f-fa6b-4715-86e7-d6313f3bb578', 'Mcleod Brothers', 'mcleod-brothers', NULL, 'McLeod Brothers is a full-service company that installs roofs, siding, and windows within New York City. As a GAF-certified Master Elite Roofing Contractor, it provides clients with supplemental upgrade options for shingle roofs, improving their lifespan and overall durability. In addition to GAF, it utilizes products made by other industry-approved manufacturers, such as asphalt shingles from CertainTeed and synthetic slate from DaVinci Roofscapes. The company is headed by Vincent Cueva, who has been working in the construction industry for over two decades.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/mcleod-brothers.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174519Z&X-Amz-Expires=43200&X-Amz-Signature=f5eb778af7f630632faa65bd5d2bf108780b8de133d83d386f70e3218267842f&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '9146363404', 'vinny.mcleod@verizon.net', 'https://mcleodbrothers.com/', '30 Church Street, Suite 1\\\\', 'New Rochelle', 'NY', '10965', 'New York City', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 12, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:13:04', '2026-09-13 17:45:19');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('d763e3f9-b4d1-4106-aafb-151a62e17a59', '1355e35e-d0d6-47fe-a502-a7c900281379', 'B&B Contracting Corp.', 'bb-contracting-corp', NULL, 'B&B Contracting Corp. serves home and business owners in New York City. The technicians install and repair sloped or flat residential roofing systems using materials from Firestone and GAF. They also work on commercial low-sloped systems built with TPO, modified bitumen, and EPDM components from CertainTeed and Johns Manville. Other services they carry out include seamless gutter projects. This family-owned contracting company has been serving customers, including those from New Jersey, for the last ten years.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/bb-contracting-corp.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174447Z&X-Amz-Expires=43200&X-Amz-Signature=830ab122a94002c93af84ae76ad4b8732fe869774d9317d238dfa1ee48fa9e37&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '7189817663', 'info@bbroofingpros.com', 'https://www.bbcontractingcorp.com/', 'Staten Island, NY ', 'Staten Island', 'NY', '', 'Staten Island', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '4.1', 9, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, NULL, NULL, '2026-09-13 09:12:43', '2026-09-20 17:37:56');
INSERT INTO `provider_profiles` (`id`, `userId`, `businessName`, `slug`, `tagline`, `description`, `logoUrl`, `logoText`, `coverImageUrl`, `phone`, `email`, `websiteUrl`, `address`, `city`, `state`, `zipCode`, `borough`, `latitude`, `longitude`, `serviceRadius`, `licenseNumber`, `sinceYear`, `isLicensed`, `isInsured`, `isBonded`, `hasWarranty`, `financingAvailable`, `emergencyService`, `bbbRating`, `verifiedYear`, `compositeRating`, `totalReviews`, `isVerified`, `isFeatured`, `isActive`, `badge`, `topPickCategory`, `featuredQuote`, `aiReviewSummary`, `aiSummaryUpdatedAt`, `createdAt`, `updatedAt`) VALUES ('72a9ab70-2c92-42b6-ad12-be830f1534d5', '372ed0a5-f0be-4dd0-b395-60bef8073bcf', 'King Remodeling Corp.', 'king-remodeling-corp', NULL, 'King Remodeling Corp. serves families and individuals seeking remodeling solutions. Serving New York City and nearby areas, it has been helping homeowners upgrade the visual appeal of their properties for more than 15 years. The company installs wood, metal, flat, and slate roofs that add elegance and beauty to homes. Its team works closely with customers to determine their preferred style and project budget. King Remodeling was included in the Best of Business Rate in 2024.', 'https://find-your-expert.0cb3820d5548d5a94afeb5daeaf5b397.r2.cloudflarestorage.com/providers/logos/king-remodeling-corp.jpg?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=094f7acff9e7816b179e268377e5910b%2F20260913%2Fauto%2Fs3%2Faws4_request&X-Amz-Date=20260913T174526Z&X-Amz-Expires=43200&X-Amz-Signature=b9c46b4160396b683ed20980a221236028bddfcd5e531b7249c7efb5dd91ff5f&X-Amz-SignedHeaders=host&x-amz-checksum-mode=ENABLED&x-id=GetObject', NULL, NULL, '7167051081', 'contact@kingremodelingcorp.com', 'https://kingremodelingcorp.com/', 'New York City, NY ', 'New York City', 'NY', '', 'Manhattan', NULL, NULL, 25, NULL, 2015, 0, 0, 0, 0, 0, 0, NULL, NULL, '5', 10, 1, 0, 1, 'Best Roofers NYC 2026', NULL, NULL, '### **King Remodeling Corp. – Professional Roofing & Exterior Remodeling Contractor**\n**Buffalo, NY & Erie County Specialists**\n\n---\n\n### **1. Overall Verdict & Trust**\nKing Remodeling Corp. earns **exceptional praise** from customers across Buffalo, Erie County, and Western New York, with **100% five-star ratings** on Google. Clients consistently highlight their **reliability, professionalism, and high-quality craftsmanship**, making them a trusted choice for roofing, siding, gutter work, and full exterior remodels. Their **clear communication, fair pricing, and attention to detail** set them apart from competitors, with multiple repeat customers planning future projects.\n\n---\n\n### **2. Key Strengths**\n✅ **Exceptional Craftsmanship** – Multiple reviews praise their **precision work**, especially in roof replacements, siding installations, and gutter systems. Customers note **durable materials** and **long-lasting results**, including repairs for storm damage.\n✅ **Punctuality & Efficiency** – Crews arrive **on time**, work **without delays**, and complete projects **quickly** while maintaining high standards.\n✅ **Speed of Response** – Clients report **immediate follow-ups** and **transparent communication**, ensuring no surprises during the process.\n✅ **Cleanup & Professionalism** – Every job leaves the site **spotless**, with crews maintaining a **respectful and organized** approach.\n✅ **Fair Pricing & Value** – Estimates are **accurate and competitive**, with no hidden fees—customers appreciate the **balance between quality and affordability**.\n\n---\n\n### **3. Pricing & Transparency**\n💰 **Value for Money** – Pricing varies by project size but falls within **reasonable ranges**:\n   - **Roofing/Repair:** $2,000–$4,000+ (for full replacements or storm damage)\n   - **Gutter Work:** $1,000–$2,000 (cleaning, repairs, or replacements)\n   - **Siding & Exterior Remodels:** Custom quotes (but consistently praised for **fair pricing**).\n\n✔ **Transparent Estimates** – Customers report **no surprises**, with King Remodeling providing **detailed quotes** before work begins.\n✔ **No Hidden Costs** – All reviews confirm **clear pricing** and **honest materials** choices.\n✔ **Newer Company (But Proven Track Record)** – One review mentions they’re newer, but clients say they’re **hardworking and reliable**, with **no complaints about quality**.\n\n---\n\n### **4. Areas of Caution / Notes**\n⚠ **No Major Red Flags** – All reviews are **unanimously positive**, with no complaints about:\n   - **Unprofessional behavior**\n   - **Poor communication**\n   - **Subpar workmanship**\n   - **Overcharging**\n\n✅ **Best for Repeat Business** – Multiple customers plan **future projects** with King Remodeling, indicating **long-term reliability**.\n\n---\n### **5. Best Suited For**\nKing Remodeling Corp. is **ideal for customers needing:**\n✔ **Roof Replacements & Repairs** (storm damage, shingle layers, Owens Corning roofs)\n✔ **Exterior Remodels** (siding, fascia, window trims, gutters)\n✔ **Gutter Cleaning & Replacement** (fast, responsive service)\n✔ **Full Home Exterior Upgrades** (dormer installations, attic transformations)\n✔ **Commercial Roofing & Siding Projects** (multiple clients plan future business with them)\n\n**Perfect for:** Homeowners in **Buffalo, Erie County, Clarence, Hamburg, and Western NY** seeking **trusted, high-quality contractors** for roofing, siding, and exterior work.\n\n---\n### **Final Recommendation**\n**10/10 – Highly Recommended!**\nKing Remodeling Corp. stands out as a **top-tier contractor** in Western New York, delivering **exceptional service, fair pricing, and outstanding results**. Whether you need a **roof replacement, siding upgrade, or full exterior remodel**, their **professional crews, attention to detail, and customer satisfaction** make them a **safe and reliable choice**.\n\n🔹 **Next Steps:**\n- Request a **free estimate** for your project.\n- Verify **licensing, insurance, and references** (all reviews confirm they’re fully insured).\n- Schedule a **consultation** to discuss materials and timelines.\n\n**Prospective customers:** Trust their reputation—this is a **contracting partner you can rely on!**', '2026-09-20 19:48:42', '2026-09-13 09:13:08', '2026-09-20 19:48:42');

