INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('0fdaeb76-53a3-4d0e-a321-513a1464086e', 'd763e3f9-b4d1-4106-aafb-151a62e17a59', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'B&B Contracting Corp. - Professional Roofing & Repair', 'bb-contracting-corp-services', 'B&B Contracting Corp. serves home and business owners in New York City. The technicians install and repair sloped or flat residential roofing systems using materials from Firestone and GAF. They also work on commercial low-sloped systems built with TPO, modified bitumen, and EPDM components from CertainTeed and Johns Manville. Other services they carry out include seamless gutter projects. This family-owned contracting company has been serving customers, including those from New Jersey, for the last ten years.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:43', '2026-09-13 09:12:43');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('bbd19b89-3a64-47b5-89eb-90a468787320', '8ec283b0-8ee3-4d1b-a1f7-65a14c2001b3', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Stop Leak Roofing - Professional Roofing & Repair', 'stop-leak-roofing-services', 'Stop Leak Roofing provides a wide range of roofing services to clients in New York City and surrounding areas. Its team conducts initial inspections to identify the problems existing in a client\'s roof and determine the right solutions needed. Its services include new roofing, flat roof installation, roof coating, and roof replacement. It also offers roof repair, shingle repair, and EPDM roofing system services. The company focuses on using updated equipment to deliver a prompt response to its customers.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:46', '2026-09-13 09:12:46');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('2e2aa836-51c8-43de-8544-682100b064b8', 'f2312eef-128a-4a67-8c87-e714c8cb8e9d', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'AK Roofing & Waterproofing - Professional Roofing & Repair', 'ak-roofing-waterproofing-services', 'AK Roofing & Waterproofing provides residential and commercial constructional improvement services to clients in New York City. It installs and repairs roofing systems using shingle and flat materials. Its crew conducts skylight installation to bring natural air and lighting to the property. Additionally, the company offers various general contracting services, including masonry works, brick pointing, foundation wall maintenance, and structure waterproofing. AK Roofing & Waterproofing has been in the industry for more than nine years.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:48', '2026-09-13 09:12:48');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('0594c9ef-e539-4232-be35-f523c17f04c5', '551a8a83-caa6-4769-bcb3-0745034de956', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'B&P Consulting Corp. - Professional Roofing & Repair', 'bp-consulting-corp-services', 'B&P Consulting Corp. is a family-owned and family-operated business that serves various customers throughout New York City, including residential property owners, engineers, business owners, and architects. For more than 15 years, the company has been installing flat roof systems, such as APP-modified bitumen,  extremely durable synthetic rubber roofing membrane (EPDM), asphalt and synthetic rubber, and thermoplastic polyolefin (TPO). It also handles foundation waterproofing and paver system installation. B&P Consulting collaborates with Westile Company and Hanover Architectural Products.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:50', '2026-09-13 09:12:50');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('e047ada1-7da9-42d2-9d47-f92e0d112d94', '25a0fd8f-b31b-4328-a293-4220b6f8f2b0', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Padovani Roofing & Construction - Professional Roofing & Repair', 'padovani-roofing-construction-services', 'Padovani Roofing & Construction serves New York City and the surrounding boroughs, offering comprehensive roofing services for both residential and commercial clients. It takes on projects involving roof installations and repairs using materials from various manufacturers. Its team also handles home improvement projects, including skylight installations, siding, chimney work, and louver installations. The company is a GAF Master Elite Contractor, IKO Certified, and Firestone Certified for EPDM and TPO flat roofing systems. It also provides special accommodations for veterans.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:52', '2026-09-13 09:12:52');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('95d6b86b-9918-45ba-9638-817832281c49', '91af576b-dbec-46d7-ad2f-6b056a84c114', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Ramapo Valley Contracting - Professional Roofing & Repair', 'ramapo-valley-contracting-services', 'Ramapo Valley Contracting serves homes and businesses in New York City and the surrounding areas.  It installs and repairs shingle and standing seam roofs, providing curb appeal and protection from the elements. The company also works with owners and tenants to revitalize outdated office spaces, transforming them into modern, functional, and aesthetically appealing work environments. The team handles new construction, custom carpentry, and interior finish work, striving to achieve exceptional results that enhance a property\'s value and durability.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:54', '2026-09-13 09:12:54');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('f463b1db-f212-4848-8d1b-8de48a666b45', '58be07a1-5640-44b3-9915-682f0692593f', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Gibraltar Home Improvements Inc - Professional Roofing & Repair', 'gibraltar-home-improvements-inc-services', 'Gibraltar Home Improvements Inc. is a family-owned and family-operated business that has been catering to clients in New York City since 1979. It offers roofing installation and remodeling services. It also handles every step of home remodeling projects, from initial consultation and design to completion. The company has received a 4.8-star Google rating based on more than 200 reviews. It was selected as the Best Roofing Company by Bethpage Federal Credit Union from 2023 to 2024.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:56', '2026-09-13 09:12:56');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('94faa49f-739e-419f-8e72-c49bc84aebf4', '593fbb14-4aed-4eac-9e3b-54256b820949', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Chief Cornerstone Roofing - Professional Roofing & Repair', 'chief-cornerstone-roofing-services', 'Chief Cornerstone Roofing addresses the construction needs of customers throughout New York City. It provides residences and commercial establishments with a wide range of roofing solutions, including inspection, installation, repair and maintenance. Its technicians, who have years of industry experience, work with different types of roofing materials, such as metal, tile, and EPDM rubber roofing, as well as asphalt shingles. They prioritize longevity and reliability by using top-quality products, adhering to industry-standard processes, and paying close attention to detail, particularly when dealing with flat roofs.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:12:58', '2026-09-13 09:12:58');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('b797b40b-c542-4483-b90d-4cb3f7811d70', 'cb76490a-4f83-484a-a42d-b4adf1f8a95b', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Al\'s Contracting - Professional Roofing & Repair', 'als-contracting-services', 'Al\'s Contracting has been providing roofing solutions to residential clients in New York City and the surrounding metros for more than 30 years. It preserves clients\' property investments by taking care of their need for regular roof installations, new construction, and re-roofing. Its team of roofers handles various types and materials to complete projects, such as lifetime asphalt shingles, roll roofing, rubber roofs, metal roofs, and Mediterranean tile, according to clients\' specifications and requirements. Al\'s Contracting utilizes major brands, including GAF, Atlas, Tamko, and Owens Corning.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:00', '2026-09-13 09:13:00');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('8e38099b-8146-4fda-a3a1-90794d884fe6', 'fcb5bcb4-2cd1-4693-9a1b-78fbef952eb1', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'A & B Roofing Corp. - Professional Roofing & Repair', 'a-b-roofing-corp-services', 'A & B Roofing Corp. works on the roofing projects of clients in New York City. The locally owned, family-run business offers a complete suite of services for all roofing needs, from repairs and replacements to new construction and preventative maintenance. It tailors services following a consultative process, taking the time to learn about each client\'s needs, wants, and precise roofing specifications. In addition, the company is able to help with gutter installation and cleaning, as well as siding installation.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:02', '2026-09-13 09:13:02');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('2ec2ea1d-e4b8-484b-b2de-4b228a17e261', '00604942-583c-4c59-91d4-5d8a019aead3', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Mcleod Brothers - Professional Roofing & Repair', 'mcleod-brothers-services', 'McLeod Brothers is a full-service company that installs roofs, siding, and windows within New York City. As a GAF-certified Master Elite Roofing Contractor, it provides clients with supplemental upgrade options for shingle roofs, improving their lifespan and overall durability. In addition to GAF, it utilizes products made by other industry-approved manufacturers, such as asphalt shingles from CertainTeed and synthetic slate from DaVinci Roofscapes. The company is headed by Vincent Cueva, who has been working in the construction industry for over two decades.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:04', '2026-09-13 09:13:04');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('7c0b4dc0-68ab-4bf0-8219-ac6259d59384', '7afb3643-51a8-4298-9dd2-9b21fc41975b', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'Jewel Construction Co - Professional Roofing & Repair', 'jewel-construction-co-services', 'Jewel Construction Co. Inc. serves property owners seeking renovation or remodeling solutions in and around New York City. For over 30 years, its team has been providing roofing services to help families and individuals improve the appeal of their properties. It works closely with customers to determine their project timeline and budget. It also performs deck installation and facade restoration. Jewel Construction Co. maintains affiliations with the NYC Landmarks Preservation Commission, the Department of Consumer Affairs NYC, and Brownstoner.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:05', '2026-09-13 09:13:05');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('b3df021f-bf55-4d7c-b917-bc320ca020a4', '72a9ab70-2c92-42b6-ad12-be830f1534d5', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'King Remodeling Corp. - Professional Roofing & Repair', 'king-remodeling-corp-services', 'King Remodeling Corp. serves families and individuals seeking remodeling solutions. Serving New York City and nearby areas, it has been helping homeowners upgrade the visual appeal of their properties for more than 15 years. The company installs wood, metal, flat, and slate roofs that add elegance and beauty to homes. Its team works closely with customers to determine their preferred style and project budget. King Remodeling was included in the Best of Business Rate in 2024.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:08', '2026-09-13 09:13:08');
INSERT INTO `listings` (`id`, `providerProfileId`, `categoryId`, `cityId`, `title`, `slug`, `description`, `status`, `pricingType`, `minPrice`, `maxPrice`, `isFeatured`, `viewCount`, `createdAt`, `updatedAt`) VALUES ('699599be-7dfb-4448-9b12-52be59433fcf', '65a83eac-f705-47b4-bc28-ef98a260c4c0', '420f19bd-8420-4c96-b42c-054a5217ab79', '19cdf860-653a-40f3-b695-bdc3c2ec44c7', 'SAS Roofing & Waterproofing - Professional Roofing & Repair', 'sas-roofing-waterproofing-services', 'SAS Roofing & Waterproofing is a family-owned and family-operated business serving clients in New York City and the surrounding areas. It caters to residential and commercial property owners in the market for roofing services. Its technicians carry out roof inspections, minor repairs, and new roof installations. They also apply waterproofing treatments on single-ply membrane roofs. In addition, the company takes on interior and exterior remodeling tasks, such as painting, plastering, stucco repair, flooring installation, and masonry.', 'ACTIVE', 'QUOTE_ONLY', NULL, NULL, 0, 0, '2026-09-13 09:13:09', '2026-09-13 09:13:09');

